from math import radians, sin, cos, asin, sqrt

EARTH_RADIUS_KM = 6371.0

def distance_km(lat1, lon1, lat2, lon2):
    """Distance between two points, used for the delivery quote."""
    p1, p2 = radians(lat1), radians(lat2)
    dp = p2 - p1
    dl = radians(lon2 - lon1)
    x = dl * cos((p1 + p2) / 2)
    return EARTH_RADIUS_KM * sqrt(x * x + dp * dp)

def quote(distance):
    return max(18.0, 12.0 + 1.4 * distance)

